&reftitle.description;

 public boolYaf_Request_Abstract::isDelete


Comprueba si la petición fue enviada con el método DELETE.

  &reftitle.examples;

   Ejemplo de Yaf_Request_Abstract::isDelete


<?php
class CommentController extends Yaf_Controller_Abstract
{
    public function removeAction()
    {
        // Suponiendo que la petición se ha enviado con DELETE /comment/remove/id/12
        var_dump($this->getRequest()->isDelete());
    }
}
?>

   &example.outputs.similar;


bool(true)
